<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Identity,PrintedBrand};
use Kulturhus\Native\Cms\Media;
$db=TestSupport::db();TestSupport::seed($db);Kulturhus\Native\Communication\Schema::install($db);Kulturhus\Native\Cms\Schema::install($db);$a=new Access($db,'admin');$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/receipt-brand';if(!is_dir($root))mkdir($root,0700,true);$im=imagecreatetruecolor(500,100);imagefill($im,0,0,imagecolorallocate($im,22,63,51));imagepng($im,$root.'/logo.png');unset($im);$media=new Media($db,$a,$root.'/media');$logo=$media->upload($root.'/logo.png','logo.png','Vereinslogo');$identity=(new Identity($db,$a))->save(['name'=>'Testverein','origin'=>'https://example.invalid','address'=>'Teststraße 1','logo_id'=>$logo['id']],0);
$n=0;function check(bool $v,string $message):void{global $n;if(!$v)throw new RuntimeException($message);$n++;echo "PASS $message\n";}
$frozen=PrintedBrand::snapshot($db,$a->club(),$identity,$root.'/media');$bytes=base64_decode($frozen['logo_png'],true);$size=getimagesizefromstring($bytes);check($frozen['logo_status']==='frozen'&&$size[0]===320&&$size[1]===64,'actual club logo resized without changing aspect ratio');check(hash('sha256',$bytes)===$frozen['logo_sha256'],'frozen logo pixels carry exact checksum');check(getimagesizefromstring(base64_decode($frozen['qr_png'],true))['mime']==='image/png','club-domain QR contains actual PNG bytes');$identity2=(new Identity($db,$a))->save(['name'=>'Geänderter Verein','origin'=>'https://changed.example','address'=>'','logo_id'=>''],$identity['version']);check($identity['origin']==='https://example.invalid'&&$frozen['logo_png']!==''&&$identity2['origin']==='https://changed.example','stored receipt identity and logo survive later club changes');check(PrintedBrand::snapshot($db,'synthetic-b',$identity,$root.'/media')['logo_status']==='unavailable','other club cannot snapshot this logo');file_put_contents($media->variant($logo['id'],'original')['path'],'changed');check(PrintedBrand::snapshot($db,$a->club(),$identity,$root.'/media')['logo_status']==='unavailable','changed original logo is not printed as a trusted image');echo "$n printed brand checks passed; actual club pixels and QR.\n";
